maya: Python snippet draft:

```python
def stream_unique(pages):
    """Yield items from pages, skipping duplicates by id (first-seen order)."""
    seen = set()
    for page in pages:
        for it in page.items:
            if it.id in seen:
                continue
            seen.add(it.id)
            yield it

# usage
for obj in stream_unique(client.stream_pages(q)):
    process(obj)
```

sam: TS draft:

```ts
async function* streamUnique(source: AsyncIterable<Page>) {
  const seen = new Set<string>();
  for await (const page of source) {
    for (const item of page.items) {
      if (seen.has(item.id)) continue;
      seen.add(item.id);
      yield item;
    }
  }
}

for await (const i of streamUnique(client.streamPages(q))) {
  handle(i);
}
```

lee: Go draft + test sketch:

```go
func StreamUnique(ch <-chan Page) <-chan Item {
  out := make(chan Item)
  go func() {
    defer close(out)
    seen := map[string]struct{}{}
    for page := range ch {
      for _, item := range page.Items {
        if _, ok := seen[item.ID]; ok { continue }
        seen[item.ID] = struct{}{}
        out <- item
      }
    }
  }()
  return out
}

// test: push pageA, pageB, pageA to channel; expect items from A then B without duplicates
```

